package com.bplus.share;
import android.net.Uri;import android.os.SystemClock;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Same-process bounded file attempts. Persisted rows survive restart; restart never silently sends. */
public final class FileJobs{
 private static final ConcurrentHashMap<String,AtomicInteger> epochs=new ConcurrentHashMap<>();private static final ConcurrentHashMap<String,Job> running=new ConcurrentHashMap<>();private static final ConcurrentHashMap<String,JSONObject> progress=new ConcurrentHashMap<>();
 private static class Job{volatile boolean cancelled;boolean watched;String peer,id;int generation;}
 private static int epoch(String id){return epochs.computeIfAbsent(id,k->new AtomicInteger()).get();}
 public static void invalidate(String peer){epochs.computeIfAbsent(peer,k->new AtomicInteger()).incrementAndGet();for(Job j:running.values())if(j.peer.equals(peer)){j.cancelled=true;Net.cancelAuto(j.id);}}
 public static void cancelWatched(String peer){for(Job j:running.values())if(j.watched&&j.peer.equals(peer)){j.cancelled=true;Net.cancelAuto(j.id);}}
 public static void cancel(String job){Job j=running.get(job);if(j!=null){j.cancelled=true;JSONObject live=progress.get(job);if(live!=null)try{JSONObject changed=new JSONObject(live.toString()).put("phase","cancelling");progress.put(job,changed);TransferService.changed(j.peer);}catch(Exception ignored){}Net.cancelAuto(job);}}
 public static JSONObject display(JSONObject m){if(m==null)return null;JSONObject live=progress.get(m.optString("job"));if(live==null)return m;try{JSONObject copy=new JSONObject(m.toString());for(Iterator<String> i=live.keys();i.hasNext();){String k=i.next();copy.put(k,live.get(k));}return copy;}catch(Exception e){return m;}}
 private static void update(String peer,JSONObject m,boolean save)throws Exception{if(save)synchronized(Store.class){JSONArray a=Store.thread(peer);boolean found=false;for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old!=null&&m.optString("id").equals(old.optString("id"))){a.put(i,new JSONObject(m.toString()));found=true;break;}}if(!found&&Store.peerById(peer)!=null)a.put(new JSONObject(m.toString()));Store.durable("thread_"+peer,a.toString());}progress.put(m.optString("job"),new JSONObject(m.toString()));if(save)TransferService.changed(peer);else TransferService.fileProgress(peer);}
 public static boolean start(JSONObject peer,Uri uri,String name,long size,boolean autoConsent,String autoId,java.util.function.BooleanSupplier allowed){if(peer==null||Store.peerById(peer.optString("id"))==null||(!autoConsent&&!FileConsent.ask(peer.optString("name"),name,size)))return false;try{JSONObject m=new JSONObject().put("id",UUID.randomUUID().toString()).put("kind","file").put("me",true).put("name",name).put("size",size).put("uri",uri.toString()).put("mime",Save.mime(name)).put("ts",System.currentTimeMillis()).put("wireId",Recall.secret()).put("recallKey",Recall.secret()).put("job",UUID.randomUUID().toString().replace("-","").substring(0,24)).put("state","sending").put("phase","connecting").put("done",0);update(peer.optString("id"),m,true);return run(peer,m,!autoId.isEmpty(),allowed);}catch(Exception e){return false;}}
 public static boolean retry(String peerId,JSONObject old){JSONObject peer=Store.peerById(peerId);if(peer==null||!FileConsent.ask(peer.optString("name"),old.optString("name"),old.optLong("size")))return false;try{JSONObject m=new JSONObject(old.toString());if(!m.optString("job").matches("[a-f0-9]{24}"))return false;return run(peer,m,false,()->true);}catch(Exception e){return false;}}
 private static boolean run(JSONObject peer,JSONObject m,boolean watched,java.util.function.BooleanSupplier allowed)throws Exception{String id=peer.optString("id"),job=m.getString("job");Job j=new Job();j.peer=id;j.id=job;j.watched=watched;synchronized(Store.class){if(Store.peerById(id)==null)return false;j.generation=epoch(id);if(running.putIfAbsent(job,j)!=null)return false;}long totalStart=SystemClock.elapsedRealtime();boolean ok=false;String failure="";try{java.util.function.BooleanSupplier live=()->!j.cancelled&&epoch(id)==j.generation&&allowed.getAsBoolean();int max=!watched&&Store.get("fileAutoRetry","1").equals("1")?3:1;for(int attempt=1;attempt<=max&&live.getAsBoolean();attempt++){long start=SystemClock.elapsedRealtime();final long[] tick={0};m.put("state","sending").put("phase","connecting").put("attempt",attempt).put("done",0).put("speed",0).remove("error");update(id,m,true);
 Net.Progress pr=(done,total)->{long now=SystemClock.elapsedRealtime();if(now-tick[0]<200&&done!=total)return;tick[0]=now;try{m.put("done",done).put("speed",done*1000/Math.max(1,now-start)).put("phase",done>=total?"confirming":"sending").put("elapsedMs",now-start);update(id,m,false);}catch(Exception ignored){}};
 Uri uri=Uri.parse(m.getString("uri"));try(android.content.res.AssetFileDescriptor fd=App.ctx().getContentResolver().openAssetFileDescriptor(uri,"r")){if(fd==null||fd.getLength()>=0&&fd.getLength()!=m.getLong("size"))throw new java.io.IOException("Source size changed");}catch(Exception missing){failure="Source unavailable or changed";break;}
 ok=Net.sendJob(App.ctx(),peer.optString("ip"),peer.optInt("port",Store.PORT),peer.optString("token"),uri,m.optString("name"),m.optLong("size"),pr,m.optString("wireId"),m.optString("recallKey"),job,live,job);m.put("timing",TransferTiming.latest());if(ok)break;failure=Net.lastError();int http=Net.lastHttp();if(http>=400&&http<500||!live.getAsBoolean()||watched||attempt>=max||!Store.get("fileAutoRetry","1").equals("1"))break;m.put("phase","retrying").put("state","sending").put("error",failure);update(id,m,true);long wait=SystemClock.elapsedRealtime()+(attempt==1?2000:5000);while(live.getAsBoolean()&&SystemClock.elapsedRealtime()<wait){if(!Store.get("fileAutoRetry","1").equals("1"))break;Thread.sleep(100);}if(!Store.get("fileAutoRetry","1").equals("1"))break;}
 boolean cancelled=!ok&&(j.cancelled||epoch(id)!=j.generation||!allowed.getAsBoolean());m.put("state",cancelled?"canceled":ok?"sent":"failed").put("phase",cancelled?"cancelled":ok?"sent":"failed").put("elapsedMs",SystemClock.elapsedRealtime()-totalStart);if(!ok)m.put("error",failure);if(epoch(id)==j.generation)update(id,m,true);return ok;
 }catch(Exception error){m.put("state",j.cancelled?"canceled":"failed").put("phase","failed").put("error",error.getClass().getSimpleName());if(epoch(id)==j.generation)update(id,m,true);return false;}finally{running.remove(job);progress.remove(job);TransferService.changed(id);}}
 public static boolean active(String job){return running.containsKey(job);}
}
